@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries = new List<WorkEntryForm.WorkEntryModel> { WorkEntryForm.WorkEntryModel.Empty() };
        }
    }

    private void AddEntry()
    {
        Entries.Add(WorkEntryForm.WorkEntryModel.Empty());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryModel model)
    {
        Entries[index] = model;
    }

    private void HandleNext()
    {
        ValidationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                ValidationError = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        OnNext.InvokeAsync(new List<WorkEntryForm.WorkEntryModel>(Entries));
    }
}
"}

