    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { WorkEntryForm.WorkEntryModel.Empty() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new()
    {
        ReferenceForm.ReferenceModel.Empty(),
        ReferenceForm.ReferenceModel.Empty()
    };

    // Step 4 state
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalResult = result;
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }
