    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
}

.review-data dd {
    margin: 0;
}

.review-work-entry {
    margin-bottom: 1rem;
    padding-left: 1rem;
    border-left: 3px solid #e0e0e0;
}

.review-dates {
    font-size: 0.9rem;
    color: #666;
}

.review-description {
    margin: 0.5rem 0 0;
    color: #555;
}

.review-reference {
    margin-bottom: 0.75rem;
    padding-left: 1rem;
    border-left: 3px solid #e0e0e0;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

