@namespace sv_f62a829300574786aa22d24634532884.Components.Pages.Apply

<div class="work-entry">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Model.Company" @oninput="UpdateCompany" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Model.Title" @oninput="UpdateTitle" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Model.StartDate.ToString("yyyy-MM-dd")" @onchange="UpdateStartDate" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDateString" @onchange="UpdateEndDate" class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Model.Description" @oninput="UpdateDescription" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Model { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.IsCurrent;
    private string EndDateString => Model.EndDate?.ToString("yyyy-MM-dd") ?? "";

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void UpdateCompany(ChangeEventArgs e) => Update(Model with { Company = GetString(e) });
    private void UpdateTitle(ChangeEventArgs e) => Update(Model with { Title = GetString(e) });
    private void UpdateDescription(ChangeEventArgs e) => Update(Model with { Description = GetString(e) });

    private void UpdateStartDate(ChangeEventArgs e)
    {
        var val = GetString(e);
        if (DateTime.TryParse(val, out var date))
            Update(Model with { StartDate = date });
    }

    private void UpdateEndDate(ChangeEventArgs e)
    {
        var val = GetString(e);
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        Update(Model with { EndDate = endDate });
    }

    private void HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        Update(Model with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Model.EndDate });
    }

    private static string GetString(ChangeEventArgs e) => e.Value?.ToString() ?? "";

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)
    {
        public static WorkEntryModel Empty() => new("", "", DateTime.Today, null, false, "");
    }
}

